INSERT INTO `b7histcat2quest668` VALUES (1,'Benin is located in the modern day _______ region of Nigeria in Edo state.','South-East','South-South ','South-West','North-Central','','B',1,'',1),(2,'The name ?Benin? was given to the administrative centre of the ancient kingdom by _______ ','Belgium ','France ','Portuguese ','Britain ','','C',1,'',2),(3,'The indigenous people of Benin speak _____language','Isan ','Edo ','YorubaD','Ibibio','','B',1,'',3),(4,'The description of Benin by Europeans as a city that was comparable with European city like _____ ','Lyon ','Manchester ','Westminster','Amsterdam','','D',1,'',4),(5,' Oyo kingdom was one of the kingdoms founded by the sons of ___________ ','Bayajida ','Eli ','Oduduwa ','Attah','','C',1,'',5),(6,'Oyo Empire came into prominence in the ________ ','15th century ','12th century ','11th century ','13th century','','A',1,'',6),(7,'The monarchical system of government in Oyo Empire was formed around powerful Obas with the title of ____________','Alaafin ','Baale ','Oyomesi ','Bashorun','','A',1,'',7),(8,'In Oyo empire, the kingmakers were known as _______________','Alaafin ','Baale ','Oyomesi ','Bashorun','','C',1,'',8),(9,'The Ogboni was the judiciary arm of the Oyo government who acted as _____________ on the powers of the Alaafin and Oyomesi.','checks and balances ','manipulators  ','decision makers ','agents of doom','','A',1,'',9),(10,'In Oyo Empire, a stubborn Alaafin can be removed from power by presenting to him ________ ','an empty egg  ','a rotten egg ','a broken calabash ','an empty calabash','','D',1,'',10),(11,'The Benin Empire was located in present-day','Nigeria ','Ethiopia ','Zimbabwe ','Kenya ','','A',1,'',11),(12,'Who was the founder of the Benin Empire? ','Oba ORANMIYAN ','Oba Ovonramwen ','Oba Ewuakpe ','Oba Ogiso','','A',1,'',12),(13,'What major body of water is associated with the Itsekiri Kingdom? ','Lake Chad ','Niger river ','Lake Victoria ',' Atlantic Ocean ','','D',1,'',13),(14,'What was the major economic activity in the Itsekiri Kingdom? ','Fishing ','Agriculture ','Trading ','Mining','','A',1,'',14),(15,'The Itsekiri Kingdom had historical links with which neighboring kingdom? ','Benin Empire ','Kanem-Bornu Empire ','Ashanti Empire ','Igbo Kingdom ','','A',1,'',15),(16,' The Itsekiri Kingdom is primarily located in which present-day country? ','Nigeria','Ghana ','Cameroon ','Togo','','A',1,'',16),(17,'Which ethnic group primarily inhabited the Old Oyo Empire?','Yoruba ','Igbo ','Hausa ','Fulani','','A',1,'',17),(18,'What type of artwork is the Benin Empire most famous for? ','Beaded jewelry ','Beaded jewelry ','Pottery ','Bronze sculptures ','','D',1,'',18),(19,'What was the major economic activity in the Itsekiri Kingdom? ','Fishing ','Agriculture ','Trading ','Mining ','','A',1,'',19),(20,'Which city served as the political and economic center of the Itsekiri Kingdom? ','Delta ','Lagos ','Port Harcourt ','Calabar','','A',1,'',20),(21,'','','','','','','',1,'',0);
