r gudanar da rayuwa ce a kowanne fanni bisa wani tsari ko hanyoyin da al&amp;rsquo;umma ta kebe, kuma ta karbe su.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;\n','&lt;p&gt;w/suna&lt;/p&gt;\n','&lt;p&gt;sadarwa&lt;/p&gt;\n','&lt;p&gt;tarbiya&lt;/p&gt;\n','&lt;p&gt;sata&lt;/p&gt;\n','','C',0.5,'',0),(46,'&lt;p&gt;Ga ire-iren tarbiya amma ban da daya&lt;/p&gt;\n','&lt;p&gt;Tarbiyar cinikayya&lt;/p&gt;\n','&lt;p&gt;Tsoron Allah&lt;/p&gt;\n','&lt;p&gt;tarbiyar karya&lt;/p&gt;\n','&lt;p&gt;tarbiyar sare amana&lt;/p&gt;\n','','C',0.5,'',0),(47,'&lt;p&gt;&lt;span style=&quot;font-size:12.0pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Calibri&amp;quot;,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;wata yarjejeniya ce da namiji da mace kanyi don zama tare da kuma samun zuri&amp;rsquo;a ta gari.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;\n','&lt;p&gt;sifa&lt;/p&gt;\n','&lt;p&gt;Aure&lt;/p&gt;\n','&lt;p&gt;fada&lt;/p&gt;\n','&lt;p&gt;aikatau&lt;/p&gt;\n','','B',0.5,'',0),(48,'&lt;p&gt;Daya baya cikin kayan dakin amarya&lt;/p&gt;\n','&lt;p&gt;masara&lt;/p&gt;\n','&lt;p&gt;tabarma&lt;/p&gt;\n','&lt;p&gt;katifa&lt;/p&gt;\n','&lt;p&gt;gado&lt;/p&gt;\n','','A',0.5,'',0),(49,'&lt;p&gt;Daya ba halayan jin dadi bane&lt;/p&gt;\n','&lt;p&gt;dariya&lt;/p&gt;\n','&lt;p&gt;kuka&lt;/p&gt;\n','&lt;p&gt;murmushi&lt;/p&gt;\n','&lt;p&gt;murna&lt;/p&gt;\n','','B',0.5,'',0),(50,'&lt;p&gt;Ware bare&lt;/p&gt;\n','&lt;p&gt;hushi&lt;/p&gt;\n','&lt;p&gt;murmushi&lt;/p&gt;\n','&lt;p&gt;fara&amp;#39;a&lt;/p&gt;\n','&lt;p&gt;farin ciki&lt;/p&gt;\n','','A',0.5,'',0),(51,'&lt;p&gt;Ware bare&lt;/p&gt;\n','&lt;p&gt;farin ciki&lt;/p&gt;\n','&lt;p&gt;razana&lt;/p&gt;\n','&lt;p&gt;firgita&lt;/p&gt;\n','&lt;p&gt;tsorata&lt;/p&gt;\n','','A',0.5,'',0),(52,'&lt;p&gt;Ware bare&lt;/p&gt;\n','&lt;p&gt;dadi&lt;/p&gt;\n','&lt;p&gt;mutuwa&lt;/p&gt;\n','&lt;p&gt;gajiya&lt;/p&gt;\n','&lt;p&gt;zafi&lt;/p&gt;\n','','A',0.5,'',0),(53,'&lt;p&gt;&lt;span style=&quot;font-size:12.0pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Calibri&amp;quot;,sans-serif&quot;&gt;&lt;span style=&quot;color:#202122&quot;&gt;--------- yana nufin yanayi da ayyuka da ke taimakawa wajen kula da lafiya da hana yaduwar cututtuka&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;\n','&lt;p&gt;sifa&lt;/p&gt;\n','&lt;p&gt;suna&lt;/p&gt;\n','&lt;p&gt;tsafta&lt;/p&gt;\n','&lt;p&gt;aikatau&lt;/p&gt;\n','','C',0.5,'',0),(54,'&lt;p&gt;Ware bare&lt;/p&gt;\n','&lt;p&gt;wanki&lt;/p&gt;\n','&lt;p&gt;fada&lt;/p&gt;\n','&lt;p&gt;wankewanke&lt;/p&gt;\n','&lt;p&gt;wanka&lt;/p&gt;\n','','B',0.5,'',0),(55,'&lt;p&gt;Ware bare dangane da kayan ado&lt;/p&gt;\n','&lt;p&gt;turare&lt;/p&gt;\n','&lt;p&gt;hoda&lt;/p&gt;\n','&lt;p&gt;manja&lt;/p&gt;\n','&lt;p&gt;mai&lt;/p&gt;\n','','C',0.5,'',0),(56,'&lt;p&gt;&lt;span style=&quot;font-size:12.0pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Calibri&amp;quot;,sans-serif&quot;&gt;&lt;span style=&quot;color:#222222&quot;&gt;----------- Dabara ce da mutum zai yi wa jikinsa sutura ya rufin asiri da kariya daga illar yanayi, sannan a tsira da mutunci.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;\n','&lt;p&gt;bayanau&lt;/p&gt;\n','&lt;p&gt;sifa&lt;/p&gt;\n','&lt;p&gt;aikatau&lt;/p&gt;\n','&lt;p&gt;tufafi&lt;/p&gt;\n','','D',0.5,'',0),(57,'&lt;p&gt;Ga tufafin maza amma banda daya&lt;/p&gt;\n','&lt;p&gt;babban riga&lt;/p&gt;\n','&lt;p&gt;alkyaba&lt;/p&gt;\n','&lt;p&gt;wando&lt;/p&gt;\n','&lt;p&gt;shimi&lt;/p&gt;\n','','D',0.5,'',0),(58,'&lt;p&gt;Ga Tufafin mata amma ban da daya&lt;/p&gt;\n','&lt;p&gt;wando&lt;/p&gt;\n','&lt;p&gt;zani&lt;/p&gt;\n','&lt;p&gt;gele&lt;/p&gt;\n','&lt;p&gt;fatari&lt;/p&gt;\n','','A',0.5,'',0),(59,'&lt;p&gt;Kristoci na ibada a ina?&lt;/p&gt;\n','&lt;p&gt;coci&lt;/p&gt;\n','&lt;p&gt;gona&lt;/p&gt;\n','&lt;p&gt;masallaci&lt;/p&gt;\n','&lt;p&gt;kasuwa&lt;/p&gt;\n','','A',0.5,'',0),(60,'&lt;p&gt;Goma a hada da ashirin sannan a cire shabiyar,nawa zai rege?&lt;/p&gt;\n','&lt;p&gt;goma sha biyar&lt;/p&gt;\n','&lt;p&gt;sha shida&lt;/p&gt;\n','&lt;p&gt;talatin&lt;/p&gt;\n','&lt;p&gt;hamsin&lt;/p&gt;\n','','A',0.5,'',0);
