INSERT INTO `basic71sttest3rdtermquest120` VALUES (1,'&lt;p&gt;&lt;span style=&quot;font-size:14.0pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Calibri&amp;quot;,&amp;quot;sans-serif&amp;quot;&quot;&gt;The principles of double entry bookkeeping states that for every debit entry, there must be corresponding&amp;hellip;&amp;hellip;&amp;hellip;&amp;hellip;&amp;hellip;entry.&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;\n','&lt;p&gt;&lt;span style=&quot;font-size:14.0pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Calibri&amp;quot;,&amp;quot;sans-serif&amp;quot;&quot;&gt;forward &lt;/span&gt;&lt;/span&gt;&lt;/p&gt;\n','&lt;p&gt;&lt;span style=&quot;font-size:14.0pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Calibri&amp;quot;,&amp;quot;sans-serif&amp;quot;&quot;&gt;backward &lt;/span&gt;&lt;/span&gt;&lt;/p&gt;\n','&lt;p&gt;&lt;span style=&quot;font-size:14.0pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Calibri&amp;quot;,&amp;quot;sans-serif&amp;quot;&quot;&gt;credit &lt;/span&gt;&lt;/span&gt;&lt;/p&gt;\n','&lt;p&gt;&lt;span style=&quot;font-size:14.0pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Calibri&amp;quot;,&amp;quot;sans-serif&amp;quot;&quot;&gt;amount&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;\n','','C',0.25,'',0),(2,'&lt;p&gt;&lt;span style=&quot;font-size:14.0pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Calibri&amp;quot;,&amp;quot;sans-serif&amp;quot;&quot;&gt;Anything of value in the double entry system is referred to as&amp;hellip;&amp;hellip;&amp;hellip;&amp;hellip;&amp;hellip;&amp;hellip;&amp;hellip;&amp;hellip;&amp;hellip;.&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;\n','&lt;p&gt;&lt;span style=&quot;font-size:14.0pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Calibri&amp;quot;,&amp;quot;sans-serif&amp;quot;&quot;&gt;debt &lt;/span&gt;&lt;/span&gt;&lt;/p&gt;\n','&lt;p&gt;&lt;span style=&quot;font-size:14.0pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Calibri&amp;quot;,&amp;quot;sans-serif&amp;quot;&quot;&gt;asset