INSERT INTO `basic7raitm3exams2025quest41` VALUES (1,'Which unit is relative to the size of the parent element?','px','%','pt','em','','B',1,'',1),(2,'Which HTML tag is used to link an external CSS file?','^style^','^css^','^script^','^link^','','D',1,'',2),(3,'Which CSS property is used to change the text color?','text-color','color','font-color','text-style','','B',1,'',3),(4,'How do you select an element with the ID \"main\"?','.main','#main','main','*main','','B',1,'',4),(5,'Which property is used to change the background color?','bgcolor','background-style','background','background-color','','D',1,'',5),(6,'What value should you use to make text bold in CSS?','font-weight: strong','font-weight: bold','font-style: bold','text-weight: bold','','B',1,'',6),(7,'How do you make all ^p^ elements have center-aligned text?','text-align: center','align: center','p-align: center','center: text','','A',1,'',7),(8,'What tag is commonly used with CSS Grid or Flexbox layout?','^table^','^div^','^form^','^p^','','B',1,'',8),(9,'Which property adds space inside an element’s border?','margin','padding','border-spacing','spacing','','B',1,'',9),(10,'Which property controls the outer space of an element?','padding','margin','spacing','border','','B',1,'',10),(11,'Which keyword is used to define a CSS animation?','@media','@style','@keyframes','@animation','','C',1,'',11),(12,'Which media type is used for screen devices in media queries?','print','screen','all','device','','B',1,'',12),(13,'Which property controls the duration of the animation?','animation-delay','animation-length','animation-duration','duration','','C',1,'',13),(14,'What does the \'infinite\' value do in animation-iteration-count?','Stops the animation','Runs the animation once','Repeats the animation forever','Speeds up the animation','','C',1,'',14),(15,'To start animation immediately, you use:','animation-delay: 0s','animation-delay: start','animation: begin','delay: none','','A',1,'',15),(16,'What does width: 100% mean?','100 pixels','Maximum width','Full width of parent','Smallest possible width','','C',1,'',16),(17,'What does this query do: @media (max-width: 768px)?','Applies if screen is wider than 768px','Applies if screen is exactly 768px','Applies if screen is 768px or smaller','Applies only to mobile','','C',1,'',17),(18,'What does @keyframes slide define?','A CSS variable','A JavaScript function','An animation sequence','A media query','','C',1,'',18),(19,'Which property tells how many times animation should run?','animation-loop','animation-count','animation-repeat','animation-iteration-count','','D',1,'',19),(20,'Which meta tag helps set responsive scaling?','^meta responsive^','^meta name=\"scale\"^','^meta name=\"viewport\"^','^meta view=\"device\"^','','C',1,'',20),(21,'What is Bootstrap?','A CMS','A web browser','A front-end framework','A file extension','','C',1,'',21),(22,'Which CSS preprocessor does Bootstrap use?','LESS','SASS','SCSS','None','','B',1,'',22),(23,'What class makes text centered in Bootstrap?','center-text','text-centered','text-center','align-center','','C',1,'',23),(24,'What class creates a grid row in Bootstrap?','.column','.grid-row','.row','.line','','C',1,'',24),(25,'What’s the default number of columns in Bootstrap grid?','6','10','12','15','','C',1,'',25),(26,'What class is used for responsive images?','.img-resize','.responsive-img','.img-fluid','.image-fit','','C',1,'',26),(27,'Which Bootstrap component creates a navigation bar?','.nav','.navbar','.navigation','.menu','','B',1,'',27),(28,'How do you add a button in Bootstrap?','^div class=\"btn\"^','^span class=\"button\"^','^button class=\"btn btn-primary\"^','^input class=\"btn-primary\"^','','C',1,'',28),(29,'Which class adds margin in Bootstrap?','.m-1','.padding','.space','.margin-1','','A',1,'',29),(30,'What attribute is used to specify the image path?','Path','Location','Source','src','','D',1,'',30),(31,'Which file extension is most commonly used for images?','.doc','.jpg','.html','.css','','B',1,'',31),(32,'What layout method helps to align items in a row?','Grid','Table','Flexbox','Block','','C',1,'',32),(33,'What is a navigation bar?','Page header','Footer','Section with links','Image','','C',1,'',33),(34,'Which tag creates a hyperlink in HTML?','^link^','^a^','^href^','^hyper^','','B',1,'',34),(35,'How do you open a link in a new tab?','target=\"open\"','target=\"new\"','target=\"_blank\"','tab=\"new\"','','C',1,'',35),(36,'What does alt attribute do in an ^img^ tag?','Gives image dimensions','Provides alternative text','Sets alignment','Adds image caption','','B',1,'',36),(37,'What does the ^footer^ tag contain?','Headline','Main content','Links, copyright','Styles','','C',1,'',37),(38,'What is a breakpoint?','A website error','Screen size where layout changes','Line of code that stops execution','CSS variable','','B',1,'',38),(39,'What symbol joins multiple conditions in a media query?','&','&&','and','+','','C',1,'',39),(40,'Which CSS property is used to change the text color?','text-color','color','font-color','text-style','','B',1,'',40);
