INSERT INTO `hausab83rdterm1stcaquest242` VALUES (1,'&lt;p style=&quot;margin-left:0in; margin-right:0in; text-align:justify&quot;&gt;&lt;span style=&quot;font-size:11pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;font-size:12.0pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;tarbiyya ce da za a cusa wa mutum, ko ya dauke ta domin yi wa kasa aiki da zuciya daya. &lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;\n\n&lt;p style=&quot;margin-left:0in; margin-right:0in; text-align:justify&quot;&gt;&lt;span style=&quot;font-size:11pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;font-size:12.0pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt; A. Taimako juna B. Kishin kasa C. Lafazi D. Kame kai.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;\n','&lt;p&gt;A&lt;/p&gt;\n','&lt;p&gt;B&lt;/p&gt;\n','&lt;p&gt;C&lt;/p&gt;\n','&lt;p&gt;D&lt;/p&gt;\n','','B',0.5,'',0),(2,'&lt;p style=&quot;margin-left:0in; margin-right:0in; text-align:justify&quot;&gt;&lt;span style=&quot;font-size:11pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;font-size:12.0pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;tana karfafa &amp;shy;&amp;shy;&amp;shy;____ A. sata B. fada C. zumunci D. rashin zaman lafiya&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;\n','&lt;p&gt;A&lt;/p&gt;\n','&lt;p&gt;B&lt;/p&gt;\n','&lt;p&gt;C&lt;/p&gt;\n','&lt;p&gt;D&lt;/p&gt;\n','','C',0.5,'',0),(3,'&lt;p style=&quot;margin-left:0in; margin-right:0in; text-align:justify&quot;&gt;&lt;span style=&quot;font-size:11pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;font-size:12.0pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt