INSERT INTO `ss1raitm3cat225quest189` VALUES (1,'What Python library is used to perform statistical calculations in the lesson? ',' Pandas ',' Math ',' NumPy ','Matplotlib','','C',1,'',1),(2,'Which function is used to find the minimum value in a NumPy array? ',' np.minimum()',' np.min()',' np.lowest()','min.array()','','B',1,'',2),(3,'What does np.max(scores) return? ','The highest score ','The average score ',' The lowest score ','The number of elements','','A',1,'',3),(4,'What is the purpose of the np.mean() function? ','To find the total sum ','To count elements ',' To find the middle value ','To calculate the average ','','D',1,'',4),(5,'Which of these best describes the median in statistics? ',' The most repeated number ','The smallest number ',' The middle number in a sorted array ',' The sum of all numbers ','','C',1,'',5),(6,'Why is the median often preferred over the mean?','  It?s easier to calculate ',' It handles extreme values better',' It shows total values ','It changes the data order ','','B',1,'',6),(7,'What does np.std(scores) calculate? ',' The standard input ','The sum of all scores ','The difference between max and min ','The spread of data (standard deviation) ','','D',1,'',7),(8,'Which one is an array in python? ',' [3, 6, 9, 12, 15, &, * ] ',' [29, 18, 30, 15, 57, 46] ',' [10, 20, 30, 40, 50, A, B] ','(78, 92, 88, 65, 75, 89, 95) ','','B',1,'',8),(9,'What is the output of np.median([10, 20, 30, 40, 50])?','30','25','35','20','','A',1,'',9),(10,'Why is understanding standard deviation useful in real life? ',' To predict the future ',' To identify repeating values','To understand how values differ from the average ',' To find errors in code ','','C',1,'',10),(11,'What is indexing in NumPy used for? ','To access elements by their positions ','To access elements by their values ',' To delete elements ',' To sort the array ','','A',1,'',11),(12,' What is the output of arr[0] if arr = np.array([10, 20, 30, 40])? ','0','10','20','30','','B',1,'',12),(13,'What does slicing arr[1:3] return from arr = np.array([10, 20, 30, 40])? ',' [10, 30] ',' [10, 20] ',' [30, 40]','[20, 30] ','','D',1,'',13),(14,' Which method changes the shape of a NumPy array? ','reshape()',' slice() ',' resize() ',' shift()','','A',1,'',14),(15,'What is the shape of arr.reshape(2, 3) for arr = np.array([1, 2, 3, 4, 5, 6])? ','1 row, 6 columns','3 rows, 2 columns  ',' 2 rows, 3 columns ',' 6 rows, 1 column','','C',1,'',15),(16,'What is the result of slicing the first three elements of arr = np.array([5, 10, 15, 20])? ','[10, 15, 20]','[5, 10, 15]  ',' [5, 10, 20] ','[5, 15, 20]','','B',1,'',16),(17,'Which function is used to convert a 1D array into a multi-dimensional array in NumPy? ',' reshape() ',' flatten()',' split()  ','arrange()','','A',1,'',17),(18,' What is required when using reshape() on an array? ',' The total number of elements must remain the same',' All elements must be even ','The array must be sorted ','The array must be two-dimensional','','A',1,'',18),(19,'Which NumPy function would you use to extract part of an array? ',' slice() ',' index() ',' slicing using [start:end]','cut()','','C',1,'',19),(20,'What is the result of np.array([1,2,3,4,5,6]).reshape(3,2)?','[[1 2], [3 4], [5 6]] ',' [[1 2 3], [4 5 6]] ',' [[1 3 5], [2 4 6]] ',' Error','','A',1,'',20);
