INSERT INTO `ss1raitm3exms25quest39` VALUES (1,'What Python library is used to perform statistical calculations in the lesson?','Pandas','Math','NumPy','Matplotlib','','C',1.5,'',1),(2,'Which function is used to find the minimum value in a NumPy array?','np.minimum()','np.min()','np.lowest()','min.array()','','B',1.5,'',2),(3,'What does np.max(scores) return?','The highest score','The average score','The lowest score','The number of elements','','A',1.5,'',3),(4,'What is the purpose of the np.mean() function?','To find the total sum','To count elements','To find the middle value','To calculate the average','','D',1.5,'',4),(5,'Which of these best describes the median in statistics?','The most repeated number','The smallest number','The middle number in a sorted array','The sum of all numbers','','C',1.5,'',5),(6,'Why is the median often preferred over the mean?','It’s easier to calculate','It handles extreme values better','It shows total values','It changes the data order','','B',1.5,'',6),(7,'What does np.std(scores) calculate?','The standard input','The sum of all scores','The difference between max and min','The spread of data (standard deviation)','','D',1.5,'',7),(8,'Which one is an array in python?','[3, 6, 9, 12, 15, &, * ]','[29, 18, 30, 15, 57, 46]','[10, 20, 30, 40, 50, A, B]','(78, 92, 88, 65, 75, 89, 95)','','B',1.5,'',8),(9,'What is the output of np.median([10, 20, 30, 40, 50])?','30','25','35','20','','A',1.5,'',9),(10,'Why is understanding standard deviation useful in real life?','To predict the future','To identify repeating values','To understand how values differ from the average','To find errors in code Matplotlib','','C',1.5,'',10),(11,'What is a Python module?','A loop structure','A variable type','A file containing Python code','A function only','','C',1.5,'',11),(12,'Which of the following is a built-in module?','random','greet','add_numbers','custom','','A',1.5,'',12),(13,'What keyword is used to use a module in Python?','open','access','include','import','','D',1.5,'',13),(14,'What does math.sqrt(9) return?','2','3','9','Error','','B',1.5,'',14),(15,'What is NumPy?','A math operation','A Python loop','A powerful library for arrays','A programming language','','C',1.5,'',15),(16,'Which command installs NumPy?','pip install numpy','python install numpy','install numpy','import numpy','','A',1.5,'',16),(17,'What is the output of np.array([1,2,3])?','A list','A set','A tuple','A NumPy array','','D',1.5,'',17),(18,'What does np.ones(3) return?','[0, 0, 0]','[1, 1, 1]','[3]','Error','','B',1.5,'',18),(19,'What is a 2D array?','A single list','A string array','An array of arrays','A loop of arrays','','C',1.5,'',19),(20,'What does arr + 5 do if arr = np.array([1, 2, 3])?','Adds 5 to each element','Adds 5 to the array name','Error','Multiplies elements by 5','','A',1.5,'',20);
