INSERT INTO `ss2cat2compstudiesquest265` VALUES (1,'What is the BASIC notation for ?(B2 ?4AC) / 2A?','((B^2-4AC)^(1/2))/(2A)','(B^2-4AC)/(2A)','(B-4AC)^(1/2)/(2A)','((B^2-4*A*C)^(1/2))/(2*A)','','D',0.25,'',1),(2,'What is the BASIC notation for X-Y / X+Y ?','(X-Y)/(X+Y)','X-Y/X+Y','(X+Y)/(X-Y)','X+Y/X-Y','','A',0.25,'',2),(3,'What is the BASIC notation for (A + B) + C / SIN(D)?','(A + B) + C / SIN(D)','A + B + C / SIN(D)','(((A + B) + C) / (SIN(D)))','A + B / SIN(D) + C','','C',0.25,'',3),(4,'What is the BASIC notation for EX+Y ?SIN (X +NY) ?','e^(X-Y) + SIN(X-N_Y)','e^(X+Y) + SIN(X+N_Y)','e^(X-Y) - SIN(X-N_Y)','(E^X+Y- SIN(X+N*Y))','','D',0.25,'',4),(5,'What is the BASIC notation for B = 1 / 4AC ?','B = 1 / (4_A_C)','B = 1 / 4_A_C','B = 1 / (4*A / C) ','B=1/4 (A*C)','','D',0.25,'',5),(6,'What does the term \"Internet\" mean?','Interconnected Network','International Network','Internal Network','None of the above','','B',0.25,'',6),(7,'What is browsing?','Searching for information on the internet','Viewing the contents of a file or group of files','Creating a new file','Deleting a file','','A',0.25,'',7),(8,'What is a browser?','A means of browsing','A type of computer virus','A type of malware','A software application for retrieving and presenting information on the World Wide Web','','D',0.25,'',8),(9,'What is a chat room?','A for a for discussing pertinent topics','A type of computer virus','A real-time online conversation between many computer users','None of the above','','C',0.25,'',9),(10,'What is a cybercaf','Internet access provider','A type of computer virus','A type of malware','A place that provides internet access to the public','','D',0.25,'',10),(11,'What is electronic mail?','A method of exchanging digital messages across the internet','A type of computer virus','A type of malware','None of the above','','A',0.25,'',11),(12,'What is a search engine?','A type of malware','A type of computer virus','A computer program that retrieves documents or files from a database or computer network','None of the above','','C',0.25,'',12),(13,'What is FTP?','File Transfer Program','File Transfer Protocol','File Transfer Process','None of the above','','B',0.25,'',13),(14,'What is HTTP?','HyperText Transfer Protocol','HyperText Transfer Program','HyperText Transfer Process','None of the above','','A',0.25,'',14),(15,'What is an ISP?','Internet Service Process','Internet Service Program','Internet Service Provider','None of the above','','C',0.25,'',15),(16,'What is the purpose of the \"@\" sign in an email address?','To separate the domain name from the site type','To link the username and the website that owns it','To indicate the end of the email address','None of the above','','A',0.25,'',16),(17,'What is the first part of an email address called?','Host','Domain','Username','Site type','','C',0.25,'',17),(18,'What determines the extension of a domain name?','The type of entity that owns the website','The name of the organization that maintains the mail service','The username of the email address','None of the above','','A',0.25,'',18),(19,'Which of the following is an example of an email address?','support.com@domain','support@domain.com','www.support@domain.org','None of the above','','B',0.25,'',19),(20,'All these are web browsers except________','Netscape Navigator','Google','Safari','IE','','B',0.25,'',20);
